@RunWith(AndroidJUnit4.class)
public class UpgradeDeviceTest {
    @Test public void categoryTreeExpandsAndMoveArchiveGesturesKeepFixtureHistory()throws Exception {
        var instrument=InstrumentationRegistry.getInstrumentation();var context=instrument.getTargetContext();Activity a=instrument.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));TestUi.ready(a);
        try{List<JSONObject> values=List.of(Ledger.obj("id","parent","entity","category","name","Housing","direction","expense","parent","","icon","house"),Ledger.obj("id","child","entity","category","name","Internet","direction","expense","parent","parent","icon","phone"),Ledger.obj("id","bank","entity","account","name","Bank","account_type","cash","currency","RUB"));int[] edits={0},archives={0};instrument.runOnMainSync(()->{a.getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);LinearLayout body=Ui.column(a);Set<String> expanded=new HashSet<>();CategoryScreen.create(a,body,values,expanded,new CategoryScreen.Actions(){public void edit(JSONObject p){edits[0]++;}public void move(JSONObject p){}public void archive(JSONObject p){archives[0]++;}public void add(String group){}});a.setContentView(Ui.scroll(a,body));assertNull(body.findViewWithTag("category.child"));body.findViewWithTag("category.parent").performClick();assertNotNull(body.findViewWithTag("category.child"));body.findViewWithTag("category.child").performClick();assertEquals(1,edits[0]);body.findViewWithTag("category.parent").performClick();assertNull(body.findViewWithTag("category.child"));assertEquals(0,archives[0]);body.findViewWithTag("category.parent").performClick();});capture("categories-0.1.6.png");}finally{instrument.runOnMainSync(a::finish);}
    }
    @Test public void russianCatalogAndDialogsDoNotChangeNumericFields()throws Exception {
        var instrument=InstrumentationRegistry.getInstrumentation();var context=instrument.getTargetContext();String original=context.getSharedPreferences("language",0).getString("locale","en");Activity a=instrument.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));TestUi.ready(a);AlertDialog[] dialog={null};
        try{instrument.runOnMainSync(()->{Strings.set(a,"ru");assertEquals("Расходы",Strings.t(a,"Expenses"));assertEquals("Основная валюта: RUB",Strings.t(a,"Base currency: RUB"));LinearLayout body=Ui.column(a);EditText number=Ui.field(a,body,"Amount","1.23456789",true);assertEquals("1.23456789",Ui.value(number));dialog[0]=new LocalizedDialog(a).setTitle("Move category").setView(body).setPositiveButton("Save",null).setNegativeButton("Cancel",null).show();assertEquals("Сохранить",dialog[0].getButton(-1).getText().toString());});capture("russian-dialog-0.1.6.png");}finally{instrument.runOnMainSync(()->{if(dialog[0]!=null)dialog[0].dismiss();Strings.set(a,original);a.finish();});}
    }
    @Test public void currencyChartAndDepositMarkersRenderFromIsolatedData()throws Exception {
        var instrument=InstrumentationRegistry.getInstrumentation();var context=instrument.getTargetContext();Activity a=instrument.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));TestUi.ready(a);
        try{List<JSONObject> values=new ArrayList<>();values.add(Ledger.obj("id","ton","entity","account","name","TON wallet","account_type","crypto","currency","TON"));values.add(Ledger.transaction("income","ton","10","TON","","","2026-10-23T12:00:00","RUB","100"));for(int day=20;day<=25;day++){JSONObject q=Rates.quote("TON","RUB",BigDecimal.valueOf(100+(day-20)*5),"Fixture","2026-10-"+day);q.put("id","q"+day);q.put("entity",day==25?"rate":"quote");values.add(q);}instrument.runOnMainSync(()->{try{a.getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);LinearLayout body=Ui.column(a);CurrencyScreen.create(a,body,values,"RUB","",new CurrencyScreen.Actions(){public void refresh(){}public void history(){}public void manual(){}public void repair(){}public void operation(String id){}});a.setContentView(Ui.scroll(a,body));}catch(Exception e){throw new AssertionError(e);}});capture("currencies-0.1.6.png");}finally{instrument.runOnMainSync(a::finish);}
    }
    @Test public void historicalRepairIsIdempotentAndRejectsStalePreview()throws Exception {
        var context=InstrumentationRegistry.getInstrumentation().getTargetContext();String name="upgrade-repair-test.db";context.deleteDatabase(name);try(Store store=new Store(context,name)){JSONObject tx=Ledger.transaction("income","ton","2","TON","","","2026-10-20T12:00:00","RUB","1");store.edit(tx);RateRepair plan=new RateRepair(store.entities(false),(cur,base,date)->Rates.quote(cur,base,new BigDecimal("100"),"Fixture",date.toString()));plan.commit(store);int count=store.events().size();assertEquals("200.00",store.type("transaction",true).get(0).getString("base_amount"));RateRepair same=new RateRepair(store.entities(false),(cur,base,date)->Rates.quote(cur,base,new BigDecimal("100"),"Fixture",date.toString()));same.commit(store);assertEquals(count,store.events().size());assertThrows(IllegalStateException.class,()->plan.commit(store));Store restored=new Store(context,"upgrade-repair-restore.db");try{restored.restore(store.backup());assertEquals(count,restored.events().size());assertTrue(restored.type("transaction",true).get(0).has("rate_before_repair"));}finally{restored.close();context.deleteDatabase("upgrade-repair-restore.db");}}finally{context.deleteDatabase(name);}
    }
    @Test public void settingsAndHomeReuseResolvedViewsWithoutRebuildingHistory()throws Exception {
        var instrument=InstrumentationRegistry.getInstrumentation();var context=instrument.getTargetContext();MainActivity a=(MainActivity)instrument.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));TestUi.ready(a);try{java.lang.reflect.Method open=MainActivity.class.getDeclaredMethod("open",String.class);open.setAccessible(true);java.lang.reflect.Field cache=MainActivity.class.getDeclaredField("cachedHome");cache.setAccessible(true);long[] duration={0};instrument.runOnMainSync(()->{try{a.getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);open.invoke(a,"More");}catch(Exception e){throw new AssertionError(e);}});TestUi.ready(a);capture("settings-0.1.6.png");instrument.runOnMainSync(()->{try{assertNotNull(findText(a.findViewById(android.R.id.content),Strings.t(a,"Appearance & language")));View home=(View)cache.get(a);if(home==null){open.invoke(a,"Home");home=(View)cache.get(a);open.invoke(a,"More");}long start=android.os.SystemClock.uptimeMillis();open.invoke(a,"Home");duration[0]=android.os.SystemClock.uptimeMillis()-start;assertSame(home,a.findViewById(android.R.id.content).findViewWithTag("ledger.ready"));java.lang.reflect.Field indexField=MainActivity.class.getDeclaredField("ledgerIndex");indexField.setAccessible(true);LedgerIndex index=(LedgerIndex)indexField.get(a);String account=index.operations.entrySet().stream().max(java.util.Comparator.comparingInt(e->e.getValue().size())).map(java.util.Map.Entry::getKey).orElse("");if(!account.isEmpty()){java.lang.reflect.Field detail=MainActivity.class.getDeclaredField("detailAccount");detail.setAccessible(true);detail.set(a,account);long enter=android.os.SystemClock.uptimeMillis();open.invoke(a,"Account");long entered=android.os.SystemClock.uptimeMillis()-enter;long back=android.os.SystemClock.uptimeMillis();open.invoke(a,"Home");long returned=android.os.SystemClock.uptimeMillis()-back;assertSame(home,a.findViewById(android.R.id.content).findViewWithTag("ledger.ready"));android.util.Log.i("UpgradeTest","Account UI build ms="+entered+", return ms="+returned);}}catch(Exception e){throw new AssertionError(e);}});android.util.Log.i("UpgradeTest","Warm home view restore ms="+duration[0]);}finally{instrument.runOnMainSync(a::finish);}
    }
    private static View findText(View v,String text){if(v instanceof TextView t&&t.getText().toString().equals(text))return v;if(v instanceof ViewGroup group)for(int i=0;i<group.getChildCount();i++){View match=findText(group.getChildAt(i),text);if(match!=null)return match;}return null;}
    private static void capture(String name)throws Exception {android.os.SystemClock.sleep(250);var instrument=InstrumentationRegistry.getInstrumentation();Bitmap image=instrument.getUiAutomation().takeScreenshot();File folder=new File(instrument.getTargetContext().getExternalFilesDir(null),"previews");folder.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(folder,name))){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
}
